'use client';

import { useEffect, useRef } from 'react';
import { useTheme } from 'next-themes';
import * as THREE from 'three';
import { getLiquidEtherSettings } from '@/lib/liquid-ether';

const vertexShader = `
  varying vec2 vUv;
  void main() { vUv = uv; gl_Position = vec4(position, 1.0); }
`;

const fragmentShader = `
  precision highp float;
  varying vec2 vUv;
  uniform vec2 uResolution;
  uniform vec2 uMouse;
  uniform vec2 uVelocity;
  uniform float uTime;
  uniform float uInteractive;
  uniform float uImpulse;
  uniform vec3 uBase;
  uniform vec3 uFluid;

  float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
  float noise(vec2 p) {
    vec2 i = floor(p); vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
  }
  float fbm(vec2 p) {
    float value = 0.0; float amplitude = 0.5;
    for (int i = 0; i < 5; i++) { value += amplitude * noise(p); p = p * 2.02 + 13.7; amplitude *= 0.5; }
    return value;
  }
  void main() {
    vec2 uv = vUv;
    uv.x *= uResolution.x / uResolution.y;
    vec2 flow = vec2(fbm(uv * 1.35 + vec2(uTime * .035, -uTime * .025)), fbm(uv * 1.35 + vec2(8.4, uTime * .03)));
    vec2 mouse = uMouse; mouse.x *= uResolution.x / uResolution.y;
    vec2 cursorDirection = uv - mouse;
    float cursorDistance = length(cursorDirection);
    float cursor = exp(-10.0 * dot(cursorDirection, cursorDirection));
    float ripple = sin(cursorDistance * 46.0 - uTime * 8.0) * exp(-5.5 * cursorDistance) * uImpulse;
    flow += normalize(cursorDirection + .0001) * cursor * uInteractive * (.82 + uImpulse * .55);
    flow += uVelocity * cursor * uInteractive * 3.2;
    float field = fbm(uv * 1.8 + flow * 2.7 + uTime * .025);
    field += cursor * uInteractive * (.65 + .22 * sin(uTime * 2.0 + field * 12.0)) + ripple * .48;
    float liquid = smoothstep(.28, .78, field);
    float highlight = smoothstep(.62, .95, field) * .13;
    vec3 color = mix(uBase, uFluid, liquid * .42);
    color += highlight;
    gl_FragColor = vec4(color, 1.0);
  }
`;

export function LiquidEtherBackground() {
  const containerRef = useRef<HTMLDivElement>(null);
  const cursorRef = useRef<HTMLDivElement>(null);
  const { resolvedTheme } = useTheme();

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const isDark = resolvedTheme === 'dark';
    const renderer = new THREE.WebGLRenderer({ antialias: false, alpha: true, powerPreference: 'low-power' });
    const scene = new THREE.Scene();
    const camera = new THREE.Camera();
    renderer.domElement.style.position = 'absolute';
    renderer.domElement.style.inset = '0';
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    renderer.domElement.style.zIndex = '0';
    container.appendChild(renderer.domElement);

    const uniforms = {
      uResolution: { value: new THREE.Vector2(1, 1) },
      uMouse: { value: new THREE.Vector2(.5, .5) },
      uVelocity: { value: new THREE.Vector2(0, 0) },
      uTime: { value: 0 },
      uInteractive: { value: getLiquidEtherSettings(window.innerWidth).interactive ? 1 : 0 },
      uImpulse: { value: 0 },
      uBase: { value: new THREE.Color(isDark ? '#0d0d0c' : '#f3f3ef') },
      uFluid: { value: new THREE.Color(isDark ? '#181817' : '#3a3a37') }
    };
    const material = new THREE.ShaderMaterial({ vertexShader, fragmentShader, uniforms });
    const geometry = new THREE.PlaneGeometry(2, 2);
    scene.add(new THREE.Mesh(geometry, material));

    const resize = () => {
      const { width, height } = container.getBoundingClientRect();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, getLiquidEtherSettings(window.innerWidth).maxPixelRatio));
      renderer.setSize(width, height, false);
      uniforms.uResolution.value.set(width, height);
    };
    let previousPointer = new THREE.Vector2(.5, .5);
    const move = (event: PointerEvent) => {
      const nextPointer = new THREE.Vector2(event.clientX / window.innerWidth, 1 - event.clientY / window.innerHeight);
      uniforms.uVelocity.value.copy(nextPointer).sub(previousPointer);
      uniforms.uImpulse.value = Math.min(1, uniforms.uVelocity.value.length() * 18 + .25);
      previousPointer.copy(nextPointer);
      uniforms.uMouse.value.copy(nextPointer);
      const cursorLayer = cursorRef.current;
      if (cursorLayer) {
        cursorLayer.style.left = `${event.clientX}px`;
        cursorLayer.style.top = `${event.clientY}px`;
        cursorLayer.style.opacity = '1';
        cursorLayer.style.transform = `translate(-50%, -50%) scale(${1 + uniforms.uImpulse.value * .28})`;
      }
    };
    resize();
    window.addEventListener('resize', resize);
    window.addEventListener('pointermove', move, { passive: true });

    let frame = 0;
    const render = (time: number) => {
      uniforms.uTime.value = time * .001;
      uniforms.uImpulse.value *= .94;
      uniforms.uVelocity.value.multiplyScalar(.94);
      renderer.render(scene, camera);
      frame = requestAnimationFrame(render);
    };
    render(0);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener('resize', resize);
      window.removeEventListener('pointermove', move);
      geometry.dispose(); material.dispose(); renderer.dispose();
      renderer.domElement.remove();
    };
  }, [resolvedTheme]);

  return <div ref={containerRef} aria-hidden="true" className="pointer-events-none fixed inset-0 -z-10 overflow-hidden">
    <div ref={cursorRef} className="absolute size-[42vmax] -translate-x-1/2 -translate-y-1/2 rounded-full opacity-0 transition-[opacity,transform] duration-150 bg-[radial-gradient(circle,rgba(0,0,0,.24)_0%,rgba(0,0,0,.08)_32%,transparent_68%)] mix-blend-multiply dark:bg-[radial-gradient(circle,rgba(255,255,255,.32)_0%,rgba(255,255,255,.1)_32%,transparent_68%)] dark:mix-blend-screen" style={{ zIndex: 1 }} />
  </div>;
}
